//\n// Membership is keyed by a student's ACTUAL graduation/departure term\n// (Student.graduationTermId) -- never by nominal yearLevel. This keeps\n// transferees (data spans programs/terms) and irregular students (graduate off\n// the standard Y1-Y4 path) safe.\n//\n// When a cluster is confirmed and compiled, each student's granular data is\n// consolidated into a write-once GraduationClusterEntry (the read-only\n// snapshot), its full detail is exported to an offline detail artifact, and the\n// granular hot rows are purged to reclaim space. Entries are permanent\n// (accreditation evidence) and intentionally have no updatedAt.\n\nmodel GraduationCluster {\n  id                      String                  @id\n  programId               String                  @map(\"program_id\")\n  graduationTermId        String                  @map(\"graduation_term_id\")\n  label                   String\n  status                  GraduationClusterStatus @default(open)\n  stats                   Json                    @default(\"{}\")\n  confirmedByUserId       String?                 @map(\"confirmed_by_user_id\")\n  peoAttainmentCapturedAt DateTime?               @map(\"peo_attainment_captured_at\")\n  confirmedAt             DateTime?               @map(\"confirmed_at\")\n  compiledAt              DateTime?               @map(\"compiled_at\")\n  archivedAt              DateTime?               @map(\"archived_at\")\n  createdAt               DateTime                @default(now()) @map(\"created_at\")\n\n  program        Program                  @relation(fields: [programId], references: [id], onDelete: Cascade)\n  graduationTerm AcademicTerm             @relation(\"GraduationClusterTerm\", fields: [graduationTermId], references: [id], onDelete: Restrict)\n  confirmedBy    user?                    @relation(\"ClusterConfirmer\", fields: [confirmedByUserId], references: [id], onDelete: SetNull)\n  students       Student[]                @relation(\"StudentCluster\")\n  entries        GraduationClusterEntry[]\n\n  @@unique([programId, graduationTermId])\n  @@index([status])\n  @@map(\"graduation_cluster\")\n}\n\nmodel GraduationClusterEntry {\n  id                     String        @id\n  clusterId              String        @map(\"cluster_id\")\n  studentId              String        @map(\"student_id\")\n  anonymizedId           String        @map(\"anonymized_id\")\n  studentStatusAtArchive StudentStatus @map(\"student_status_at_archive\")\n  isGraduationEntry      Boolean       @default(true) @map(\"is_graduation_entry\")\n  graduatedAt            DateTime?     @map(\"graduated_at\")\n  compiledData           Json          @default(\"{}\") @map(\"compiled_data\")\n  peoAttainment          Json          @default(\"{}\") @map(\"peo_attainment\")\n  detailArtifactUrl      String?       @map(\"detail_artifact_url\")\n  purgedRowCounts        Json          @default(\"{}\") @map(\"purged_row_counts\")\n  createdAt              DateTime      @default(now()) @map(\"created_at\")\n\n  cluster GraduationCluster @relation(fields: [clusterId], references: [id], onDelete: Cascade)\n  student Student           @relation(fields: [studentId], references: [id], onDelete: Restrict)\n\n  @@unique([studentId])\n  @@unique([clusterId, anonymizedId])\n  @@index([clusterId])\n  @@map(\"graduation_cluster_entry\")\n}\n",
